public static class SmokestackAssetBuilder {
 const string Root="Assets/_Anseong/Art/Environment/Assets/Smokestack";
 const string Gen=Root+"/Generated";
 const string Output="C:/Users/Admin/Documents/ChatGPT/안성제철/output";
 static Material shell,rust,inside,brick,smoke;
 static void Folder(string path){if(AssetDatabase.IsValidFolder(path))return;Folder(Path.GetDirectoryName(path).Replace('\\','/'));AssetDatabase.CreateFolder(Path.GetDirectoryName(path).Replace('\\','/'),Path.GetFileName(path));}
 static Material Mat(string name,Color color){string path=Gen+"/"+name+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(mat)return mat;mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));mat.color=color;mat.SetFloat("_Smoothness",.17f);AssetDatabase.CreateAsset(mat,path);return mat;}
 static Mesh Tube(string name,float bottom,float top,float height,int seed){string path=Gen+"/"+name+".asset";var previous=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(previous)return previous;var verts=new List<Vector3>();var triangles=new[]{new List<int>(),new List<int>(),new List<int>()};const int sides=40,rows=12;var random=new System.Random(seed);
  void Quad(Vector3 a,Vector3 b,Vector3 c,Vector3 d,int material){int n=verts.Count;verts.AddRange(new[]{a,b,c,d});triangles[material].AddRange(new[]{n,n+1,n+2,n,n+2,n+3});}
  Vector3 V(float radius,float y,int i){float a=i*2*Mathf.PI/sides;return new Vector3(Mathf.Cos(a)*radius,y,Mathf.Sin(a)*radius);}
  for(int i=0;i<sides;i++){for(int j=0;j<rows;j++){float a=(float)j/rows,b=(float)(j+1)/rows;float r0=Mathf.Lerp(bottom,top,a),r1=Mathf.Lerp(bottom,top,b);int m=(j==0||j==rows-1||((i*7+seed)%13<2&&random.NextDouble()<.7))?1:0;
   Quad(V(r0,a*height,i),V(r1,b*height,i),V(r1,b*height,i+1),V(r0,a*height,i+1),m);
   Quad(V(r0-.18f,a*height,i+1),V(r1-.18f,b*height,i+1),V(r1-.18f,b*height,i),V(r0-.18f,a*height,i),2);
  }Quad(V(top,height,i),V(top-.18f,height,i),V(top-.18f,height,i+1),V(top,height,i+1),1);Quad(V(bottom,0,i+1),V(bottom-.18f,0,i+1),V(bottom-.18f,0,i),V(bottom,0,i),1);}
  var mesh=new Mesh{name=name};mesh.SetVertices(verts);mesh.subMeshCount=3;for(int i=0;i<3;i++)mesh.SetTriangles(triangles[i],i);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);return mesh;
 }
 static GameObject Shell(string name,Mesh mesh,Transform parent,Vector3 position,Material outer){var g=new GameObject(name);g.transform.SetParent(parent,false);g.transform.localPosition=position;g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterials=new[]{outer,rust,inside};return g;}
 static Material SmokeMaterial(){string path=Gen+"/Smoke.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(mat)return mat;var texture=new Texture2D(64,64,TextureFormat.RGBA32,false);for(int y=0;y<64;y++)for(int x=0;x<64;x++){float radius=new Vector2((x-31.5f)/31.5f,(y-31.5f)/31.5f).magnitude;float alpha=Mathf.Pow(Mathf.Clamp01(1-radius),1.7f);texture.SetPixel(x,y,new Color(1,1,1,alpha));}texture.Apply();File.WriteAllBytes(Gen+"/SmokeSoft.png",texture.EncodeToPNG());Object.DestroyImmediate(texture);AssetDatabase.ImportAsset(Gen+"/SmokeSoft.png");mat=new Material(Shader.Find("Universal Render Pipeline/Particles/Unlit"));mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(Gen+"/SmokeSoft.png"));mat.SetFloat("_Surface",1);mat.SetFloat("_Blend",0);mat.SetFloat("_SrcBlend",5);mat.SetFloat("_DstBlend",10);mat.SetFloat("_ZWrite",0);mat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");mat.SetOverrideTag("RenderType","Transparent");mat.renderQueue=3000;AssetDatabase.CreateAsset(mat,path);return mat;}
 static ParticleSystem Particles(string name,Transform parent,Vector3 position,bool loop,Color color,float size,float speed,float rate){var g=new GameObject(name);g.transform.SetParent(parent,false);g.transform.localPosition=position;g.transform.localRotation=Quaternion.Euler(-90,0,0);var p=g.AddComponent<ParticleSystem>();p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=p.main;main.loop=loop;main.playOnAwake=loop;main.duration=loop?6:2;main.startLifetime=loop?new ParticleSystem.MinMaxCurve(3,6):new ParticleSystem.MinMaxCurve(1,3);main.startSize=new ParticleSystem.MinMaxCurve(size*.6f,size);main.startSpeed=new ParticleSystem.MinMaxCurve(speed*.6f,speed);main.startColor=color;main.simulationSpace=ParticleSystemSimulationSpace.World;main.maxParticles=loop?120:100;var emission=p.emission;emission.rateOverTime=rate;var shape=p.shape;shape.shapeType=ParticleSystemShapeType.Cone;shape.angle=15;shape.radius=1;var over=p.colorOverLifetime;over.enabled=true;var gradient=new Gradient();gradient.SetKeys(new[]{new GradientColorKey(Color.white,0),new GradientColorKey(Color.white,1)},new[]{new GradientAlphaKey(0,0),new GradientAlphaKey(.55f,.12f),new GradientAlphaKey(0,1)});over.color=gradient;var grow=p.sizeOverLifetime;grow.enabled=true;grow.size=new ParticleSystem.MinMaxCurve(1,AnimationCurve.Linear(0,.4f,1,2));g.GetComponent<ParticleSystemRenderer>().sharedMaterial=smoke;return p;}
 [MenuItem("Anseong/Art/Build Smokestack Asset")]
 public static void Build(){Folder(Gen);shell=Mat("WeatheredGray",new Color(.52f,.51f,.47f));rust=Mat("Rust",new Color(.34f,.19f,.13f));inside=Mat("SootInterior",new Color(.09f,.085f,.075f));brick=Mat("RedFoundation",new Color(.48f,.24f,.17f));smoke=SmokeMaterial();
  var root=new GameObject("Smokestack");var controller=root.AddComponent<Smokestack>();var foundation=Shell("Flared_Red_Base",Tube("Base",4.2f,2.2f,5,4),root.transform,Vector3.zero,brick);foundation.AddComponent<BoxCollider>().size=new Vector3(7,10,7);
  var bodies=new List<Rigidbody>();for(int i=0;i<6;i++){float bottom=Mathf.Lerp(2.2f,1.2f,(float)i/6),top=Mathf.Lerp(2.2f,1.2f,(float)(i+1)/6);var part=Shell("Shell_"+i,Tube("HollowSection_"+i,bottom,top,12.5f,i+10),root.transform,new Vector3(0,5+i*12.5f,0),shell);var collision=part.AddComponent<MeshCollider>();collision.sharedMesh=part.GetComponent<MeshFilter>().sharedMesh;collision.convex=true;var body=part.AddComponent<Rigidbody>();body.isKinematic=true;body.mass=8000;body.linearDamping=.2f;body.angularDamping=.8f;part.AddComponent<SmokestackHit>();bodies.Add(body);}
  var outlet=Particles("Operating_Exhaust",root.transform,new Vector3(0,80,0),true,new Color(.65f,.65f,.62f,.25f),4,3,5);var rupture=Particles("Residual_Exhaust_Leak",root.transform,Vector3.zero,true,new Color(.38f,.37f,.34f,.4f),5,3,12);var ruptureMain=rupture.main;ruptureMain.playOnAwake=false;var dust=Particles("Break_Dust",root.transform,Vector3.zero,false,new Color(.49f,.43f,.34f,.7f),7,7,0);controller.Configure(bodies.ToArray(),outlet,rupture,dust);
  var prefab=PrefabUtility.SaveAsPrefabAsset(root,Root+"/Smokestack.prefab");Object.DestroyImmediate(root);
  var group=new GameObject("Smokestack_Group");for(int i=0;i<3;i++){var item=(GameObject)PrefabUtility.InstantiatePrefab(prefab);item.name="Smokestack_"+(70+i*10)+"m";item.transform.SetParent(group.transform,false);item.transform.localPosition=new Vector3((i-1)*13,0,i*6);item.transform.localScale=Vector3.one*((70+i*10)/80f);}PrefabUtility.SaveAsPrefabAsset(group,Root+"/Smokestack_Group.prefab");Object.DestroyImmediate(group);
  EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects,NewSceneMode.Single);var test=(GameObject)PrefabUtility.InstantiatePrefab(prefab);var extra=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/Smokestack_Group.prefab"));extra.transform.position=new Vector3(-45,0,45);var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.name="Ground";floor.transform.position=new Vector3(0,-1,0);floor.transform.localScale=new Vector3(300,2,300);floor.GetComponent<Renderer>().sharedMaterial=Mat("Ground",new Color(.22f,.24f,.23f));var camera=Camera.main;camera.transform.position=new Vector3(120,85,-145);camera.transform.LookAt(new Vector3(-12,38,25));camera.fieldOfView=43;var light=Object.FindFirstObjectByType<Light>();light.intensity=2;light.transform.rotation=Quaternion.Euler(40,-30,0);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.6f,.65f,.7f);camera.backgroundColor=new Color(.35f,.48f,.6f);camera.clearFlags=CameraClearFlags.SolidColor;var demo=new GameObject("Space_Break_R_Reset").AddComponent<SmokestackDemo>();demo.Configure(test.GetComponent<Smokestack>(),Output);EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/_Anseong/Scenes/Sandbox/Sandbox_Smokestack.unity");AssetDatabase.SaveAssets();Debug.Log("SMOKESTACK_BUILD_PASS height=80 sections=6 variants=70/80/90");
 }
